(127, 'Aku Berani Jujur', 'Nurul Ihsan', 'Pendidikan Karakter', NULL, 'Buku tentang pentingnya berkata jujur.', 'jujur, karakter, moral, keberanian, anak', 'assets/uploads/covers/cover_6a39171e6817e8.77694466.jpg', NULL, '2026-06-22 08:10:57', '2026-06-22 12:40:13'),
(128, 'Aku Bisa Jadi Presiden yang Dicintai', 'Cundoko', 'Pendidikan Karakter', NULL, 'cerita anak tentang cita-cita menjadi pemimpin yang baik.', 'presiden, kepemimpinan, dicintai rakyat, tanggung jawab', 'assets/uploads/covers/cover_6a391749f1bf27.35007098.jpeg', NULL, '2026-06-22 08:10:57', '2026-06-22 12:40:13'),
(129, 'Aku Bisa Menjadi Hakim yang Bijak', 'Cundoko', 'Pendidikan Karakter', NULL, 'buku anak tentang profesi hakim dan pentingnya kebijaksanaan.', 'hakim, bijak, adil, profesi', 'assets/uploads/covers/cover_6a391766a20f73.56234548.jpg', NULL, '2026-06-22 08:10:57', '2026-06-22 12:40:13'),
(130, 'Aku Cinta Tanah Air', 'Hamonangan Sigalingging', 'Pendidikan Karakter', NULL, 'Buku ini merupakan seri bacaan pengayaan pendidikan karakter dan sosial yang dirancang khusus untuk anak-anak tingkat sekolah dasar. Ditulis oleh Hamonangan Sigalingging, materi di dalam buku ini disajikan lewat bahasa yang singkat, jelas, serta narasi harian yang mudah dipahami. Isi buku ini fokus menanamkan nilai-nilai nasionalisme, rasa bangga terhadap bangsa, kepedulian sosial, serta pemahaman dasar mengenai fungsi layanan masyarakat (seperti kantor desa) demi memupuk rasa cinta tanah air sejak dini', 'tanah air, cinta Indonesia, karakter, kebangsaan, anak', 'assets/uploads/covers/cover_6a4f248d0ddef1.20708760.png', NULL, '2026-06-22 08:10:57', '2026-07-09 04:33:17'),
(131, 'Aku dan Keluargaku', 'Harlina Pribadi', 'Keluarga', NULL, 'Buku tentang kehidupan anak bersama keluarganya.', 'keluarga, kebersamaan, rumah, kasih sayang, anak', 'assets/uploads/covers/cover_6a3917b0306ac8.09269612.jpg', NULL, '2026-06-22 08:10:57', '2026-06-22 12:40:13'),
(132, 'Aku dan Temanku', 'Harlina Pribadi', 'Persahabatan', NULL, 'Buku tentang hubungan pertemanan dan saling menghargai.', 'teman, persahabatan, kerja sama, anak, sosial', 'assets/uploads/covers/cover_6a3917caf12935.11903600.jpg', NULL, '2026-06-22 08:10:57', '2026-06-22 12:40:13'),
(133, 'Aku Mengenal Kekayaan Alam di Indonesia', 'Phindak Tuparin', 'Buku Pengetahuan Alam', NULL, 'Buku ini merupakan bacaan sains populer anak yang dirancang untuk memperkenalkan melimpahnya potensi alam yang dimiliki oleh bumi Nusantara. Ditulis secara komunikatif oleh Phindak Tuparin, materi di dalamnya mengajak pembaca cilik mengamati kekayaan alam di permukaan seperti area hutan, gunung, laut, sektor pertanian, perkebunan, hingga harta karun tambang di bawah tanah Indonesia sekaligus mengulas berbagai manfaatnya bagi kehidupan manusia sehari-hari', 'kekayaan alam, Indonesia, sumber daya, alam, pengetahuan', 'assets/uploads/covers/cover_6a4f1bc7603440.96862441.png', NULL, '2026-06-22 08:10:57', '2026-07-09 03:55:51'),
(134, 'Aku Mengenal Lingkungan Hidup di Kota dan di Desa', 'Phindak Tuparin', 'Lingkungan Hidup', NULL, 'Buku yang membandingkan lingkungan hidup di kota dan di desa.', 'kota, desa, lingkungan, perbedaan, kehidupan', 'assets/uploads/covers/cover_6a39183fa3fb89.57553136.jpg', NULL, '2026-06-22 08:10:57', '2026-06-22 12:40:13'),
(135, 'Alam Sekitar Kita', 'Muhammad Tadir', 'Lingkungan', NULL, 'Buku tentang alam dan lingkungan di sekitar kita.', 'alam, lingkungan, sekitar, pengetahuan, kehidupan', 'assets/uploads/covers/cover_6a4f1e308178d6.88628148.png', NULL, '2026-06-22 08:10:57', '2026-07-09 04:06:08'),
(136, 'Alamku Duniaku', 'N. Antasari', 'Pendidikan Lingkungan', NULL, 'bacaan anak tentang alam dan dunia sekitar.', 'alam, lingkungan, anak', 'assets/uploads/covers/cover_6a39186823ac19.68158138.jpg', NULL, '2026-06-22 08:10:57', '2026-06-22 12:40:13'),
(137, 'Subhanallah Allah Menciptakan Unta', 'Nunik Avianti Agus', 'Religi Anak', NULL, 'Buku ini merupakan bagian dari \"Seri Keajaiban Hewan\" yang dirancang khusus sebagai bacaan edukasi Islami bagi anak-anak. Ditulis oleh Nuniek Avianti Agus, isi buku ini mengulas keunikan anatomi dan kemampuan bertahan hidup hewan unta di gurun pasir yang ekstrem. Melalui pendekatan sains populer yang diselaraskan dengan nilai-nilai tauhid, pembaca cilik diajak untuk mengagumi kebesaran dan kecerdasan desain Allah SWT dalam menciptakan makhluk-Nya.', 'unta, ciptaan Allah, religi, hewan, anak', 'assets/uploads/covers/cover_6a4f120c6b2421.43358736.png', NULL, '2026-06-22 08:10:57', '2026-07-09 03:14:20'),
(138, 'Anak Indonesia Anti-Kekerasan', 'Sholehhuddin Ade Ghazali', 'Pendidikan Karakter', NULL, 'Buku pengayaan karakter ini dirancang sebagai panduan edukatif bagi generasi muda untuk membangun budaya damai dan menolak segala bentuk kekerasan sejak dini. Ditulis oleh Sholehuddin dan Ade Ghazali, isi buku ini memberikan pemahaman kepada anak-anak mengenai pentingnya menyikapi perbedaan dengan kepala dingin, menghindari perilaku perundungan (bullying), serta menerapkan sikap saling menyayangi, menghargai, dan toleransi. Tujuannya adalah menciptakan lingkungan pergaulan yang aman, inklusivitas, dan ramah anak di seluruh Indonesia.', 'anti kekerasan, anak, aman, karakter, perlindungan', 'assets/uploads/covers/cover_6a4f216a699250.58632649.png', NULL, '2026-06-22 08:10:57', '2026-07-09 04:19:54'),
(139, 'Anak Kecil dengan Biolanya', 'Pavel Vezhinov', 'Serial Cerita Klasik', NULL, 'Cerita klasik tentang seorang anak kecil dan kehidupannya yang berkaitan dengan biola.', 'anak kecil, biola, musik, klasik, cerita', 'assets/uploads/covers/cover_6a3918edd3a751.67084244.jpg', NULL, '2026-06-22 08:10:57', '2026-06-22 12:40:13'),
(140, 'Anak Revolusi', 'Rasyid Akbar', 'Sejarah', NULL, 'Cerita bernuansa sejarah tentang semangat perjuangan dan perubahan.', 'revolusi, perjuangan, sejarah, pemuda, keberanian', 'assets/uploads/covers/cover_6a4f1043e24cb7.69544134.png', NULL, '2026-06-22 08:10:57', '2026-07-09 03:06:43'),
(141, 'Aneka Olahan Beras Ketan', 'Nenden Rilla Artistiana', 'Kuliner', NULL, 'kumpulan olahan makanan berbahan dasar beras ketan.', 'beras ketan, olahan, resep', 'assets/uploads/covers/cover_6a4f28f90cd5c3.89282985.png', NULL, '2026-06-22 08:10:57', '2026-07-09 04:52:09'),
(142, 'Aneka Olahan Pisang', 'Nenden Rilla Artistiana', 'Kuliner', NULL, 'kumpulan resep makanan berbahan dasar pisang.', 'pisang, olahan, resep', 'assets/uploads/covers/cover_6a4f2902219338.66918126.png', NULL, '2026-06-22 08:10:57', '2026-07-09 04:52:18'),
