(144, 'Arjuna Wiwaha', 'Sunardi D.M.', 'Sastra Klasik', NULL, 'kisah klasik Arjuna Wiwaha dalam bentuk bacaan sastra.', 'Arjuna, wayang, epik, sastra klasik, budaya', 'assets/uploads/covers/cover_6a39196a6e20f9.96595933.jpg', NULL, '2026-06-22 08:10:57', '2026-06-22 12:40:13'),
(145, 'Asal Mula Danau Toba', 'Tira Ikranegara', 'Cerita Rakyat', NULL, 'kisah asal mula Danau Toba dan Pulau Samosir dalam bentuk cerita rakyat. (Pustaka Berwarna)', 'Danau Toba, Samosir, legenda, cerita rakyat', 'assets/uploads/covers/cover_6a4f0c9440b748.14227166.png', NULL, '2026-06-22 08:10:57', '2026-07-09 02:51:00'),
(146, 'Asal Mula Danau Toba dan Dongeng Terkenal Lainnya', 'Yustitia Angelia', 'Legenda', NULL, 'Kumpulan cerita rakyat, dengan kisah asal mula Danau Toba sebagai cerita utama.', 'Danau Toba, legenda, dongeng, Sumatera, cerita rakyat', 'assets/uploads/covers/cover_6a4f16f313cb48.22297878.png', NULL, '2026-06-22 08:10:57', '2026-07-09 03:35:15'),
(147, 'Asap Itu Masih Mengepul', 'Ratmana', 'Cerita Remaja', NULL, 'Cerita bernuansa sosial dengan latar peristiwa yang sedang terjadi.', 'asap, konflik, kehidupan, sosial, cerita', 'assets/uploads/covers/cover_6a3919d5dd57c2.96901781.jpg', NULL, '2026-06-22 08:10:57', '2026-06-22 12:40:13'),
(148, 'Astronomi dan Bumi', 'Timas Community', 'Sains', NULL, 'buku visual yang mengenalkan astronomi dan bumi.', 'astronomi, bumi, ruang angkasa, sains, pengetahuan', 'assets/uploads/covers/cover_6a4f2204ba9df4.86827585.png', NULL, '2026-06-22 08:10:57', '2026-07-09 04:22:28'),
(149, 'Atheis', 'Achdiat K. Mihardja', 'Sastra Klasik', NULL, 'novel klasik Indonesia yang membahas pergulatan pemikiran dan keyakinan.', 'novel, ideologi, konflik batin', 'assets/uploads/covers/cover_6a391a04b40740.15394163.jpg', NULL, '2026-06-22 08:10:57', '2026-06-22 12:40:13'),
(150, 'Azab dan Sengsara', 'Merari Siregar', 'Sastra Klasik', NULL, 'novel klasik tentang konflik cinta dan adat.', 'sastra lama, tragedi, percintaan', 'assets/uploads/covers/cover_6a391a2aa8e2a3.86736970.jpg', NULL, '2026-06-22 08:10:57', '2026-06-22 12:40:13'),
(151, 'Baham Pahlawan Sumbawa', 'Ratsu', 'Cerita Rakyat Daerah', NULL, 'Buku fiksi sejarah ini mengangkat kisah kepahlawanan lokal dari tanah Sumbawa, Nusa Tenggara Barat, mengenai sosok pejuang bernama Baham. Ditulis secara memikat oleh Ratsu, narasi setebal 72 halaman ini mengisahkan tentang Perang Baham (kejadian kisaran tahun 1906 dan 1921) dalam memimpin gerakan rakyat di wilayah Sumbawa Selatan untuk menentang serta menekan cengkeraman kolonial Belanda.', 'Sumbawa, pahlawan, daerah, perjuangan, cerita rakyat', 'assets/uploads/covers/cover_6a391a4a32ae04.70130921.jpg', NULL, '2026-06-22 08:10:57', '2026-07-09 03:29:37'),
(152, 'Bahasa Indonesia Bacaan Jilid 6a', 'belum terbaca jelas', 'Bahasa Indonesia', NULL, 'buku bacaan pelajaran bahasa Indonesia untuk tingkat dasar.', 'bahasa Indonesia, bacaan, jilid 6a, sekolah dasar, pelajaran', 'assets/uploads/covers/cover_6a4f1f68ec79b7.05557221.png', NULL, '2026-06-22 08:10:57', '2026-07-09 04:11:20'),
(153, 'Baktiku untuk Negeriku', 'Sukri', 'Pendidikan Karakter', NULL, 'bacaan tentang pengabdian dan rasa cinta tanah air.', 'bakti, negeri, nasionalisme', 'assets/uploads/covers/cover_6a391a6681d485.16316520.jpg', NULL, '2026-06-22 08:10:57', '2026-06-22 12:40:13'),
(154, 'Melestarikan Karakter Bangsa Indonesia', 'Edi Warsidi', 'Buku Pengembangan Karakter', NULL, 'Buku ini merupakan bacaan pengayaan pendidikan karakter yang dirancang untuk menguatkan nilai-nilai moral dan kebangsaan pada generasi muda. Ditulis oleh Edi Warsidi, isi buku ini memberikan panduan praktis dan ulasan mengenai pentingnya menjaga, menerapkan, serta melestarikan kepribadian luhur bangsa Indonesia—seperti gotong royong, sopan santun, dan toleransi—di tengah era perkembangan zaman agar jati diri nasional tetap terjaga kokoh', 'karakter bangsa, nilai moral, budi pekerti, kepribadian anak, nasionalisme, pelestarian budaya', 'assets/uploads/covers/cover_6a4f18162a7be2.57726305.png', NULL, '2026-06-22 08:10:57', '2026-07-09 03:40:06'),
(155, 'Batu Menangis', 'Djoko Dwimanto', 'Cerita Rakyat', NULL, 'Cerita rakyat Indonesia tentang legenda Batu Menangis.', 'legenda, batu, dongeng, rakyat, moral', 'assets/uploads/covers/cover_6a391a904b4150.96386094.jpg', NULL, '2026-06-22 08:10:57', '2026-06-22 12:40:13'),
(156, 'Belantara Jakarta', 'Supriadi', 'Fiksi Anak', NULL, 'Buku setebal 66 halaman ini merupakan novel anak klasik yang diterbitkan oleh PT. Indah Jaya di Bandung. Cerita di dalamnya dikemas untuk pembaca tingkat sekolah dasar dengan menyisipkan beberapa ilustrasi gambar hitam putih yang menarik sepanjang alur penceritaan. Buku ini mengisahkan tentang dinamika petualangan, jalinan persahabatan, serta perjuangan hidup anak-anak jalanan di tengah kerasnya kota besar. Melalui latar belakang kehidupan urban ibu kota, penulis menyelipkan berbagai pesan moral, nilai sosial, ketabahan, dan pentingnya semangat pantang menyerah bagi para pembaca muda dalam menghadapi tantangan hidup.', 'Jakarta, kehidupan, kota', 'assets/uploads/covers/cover_6a391aa9c9abb5.55159602.jpg', NULL, '2026-06-22 08:10:57', '2026-07-09 05:30:11'),
(157, 'Berburu Rahasia Alam Semesta', 'Nikky Firmansyah', 'Sains', NULL, 'Buku ini merupakan buku pengayaan pengetahuan sains populer yang dirancang khusus sebagai materi bacaan edukatif untuk anak-anak sekolah dasar dan remaja. Melalui penjelasan yang sederhana dan komunikatif, buku ini mengajak para pembaca muda untuk bertualang dan mengeksplorasi misteri jagat raya. Materi di dalamnya mengulas berbagai fenomena menarik di ruang angkasa, mulai dari asal-usul pembentukan alam semesta melalui teori dentuman besar, karakteristik bintang dan galaksi, sistem tata surya kita, hingga pengenalan berbagai macam benda langit dan peristiwa alam di antariksa. Pembahasan yang dilengkapi dengan ilustrasi visual ini bertujuan untuk mempermudah pemahaman konsep astronomi dasar sekaligus merangsang minat anak terhadap ilmu pengetahuan alam sejak dini.', 'semesta, sains, eksplorasi', 'assets/uploads/covers/cover_6a4f325b612245.68788358.png', NULL, '2026-06-22 08:10:57', '2026-07-09 05:32:11'),
(158, 'Berjuang Mengukir Prestasi', 'Siti Nur Fitria, Hika D. Asril Putra, Sukma Awliyawati', 'Motivasi', NULL, 'buku yang mendorong anak untuk berusaha dan meraih prestasi.', 'prestasi, perjuangan, semangat, motivasi, sukses', 'assets/uploads/covers/cover_6a4f1ea800fb12.85709855.png', NULL, '2026-06-22 08:10:57', '2026-07-09 04:08:08'),
(159, 'Bersaing Sehat Mewujudkan Potensiku', 'Edi Sukmana', 'Pendidikan Karakter', NULL, 'Buku ini merupakan bacaan pengayaan karakter anak yang dirancang untuk membangun mentalitas kompetisi yang positif sejak dini. Ditulis oleh Edi Sukmana, isi buku ini memberikan panduan dan motivasi kepada anak-anak mengenai bagaimana cara mengenali bakat diri serta berani menunjukkan prestasi melalui persaingan yang sehat, jujur, dan sportif tanpa harus menjatuhkan orang lain demi mewujudkan potensi terbaik mereka.', 'persaingan sehat, potensi, motivasi, anak, karakter', 'assets/uploads/covers/cover_6a4f19221e0088.19324721.png', NULL, '2026-06-22 08:10:57', '2026-07-09 03:44:34'),
(160, 'Bersyukur Itu Indah', 'Iwan Setiawan', 'Pendidikan Karakter', NULL, 'buku yang menanamkan sikap bersyukur dalam kehidupan sehari-hari.', 'syukur, karakter, moral, kebiasaan baik, anak', 'assets/uploads/covers/cover_6a4f20d82a1623.63187205.png', NULL, '2026-06-22 08:10:57', '2026-07-09 04:17:28'),
(161, 'Beternak Ayam, Yuk!', 'Yoeni Erlyna', 'Peternakan', NULL, 'panduan atau cerita anak tentang beternak ayam.', 'ayam, ternak, peternakan', 'assets/uploads/covers/cover_6a4f2919a59829.59113921.png', NULL, '2026-06-22 08:10:57', '2026-07-09 04:52:41');
INSERT INTO `books` (`id`, `title`, `author`, `category`, `year`, `description`, `keywords`, `cover_image`, `deleted_at`, `created_at`, `updated_at`) VALUES
(162, 'Bincang Riang Tentang Binatang Buas', 'Bambang Trimansyah', 'Pengetahuan Hewan', NULL, 'Buku ini merupakan bacaan sains populer dan edukatif yang dikemas secara interaktif dan menyenangkan untuk mengenalkan dunia hewan kepada anak-anak. Ditulis oleh pakar perbukuan Bambang Trimansyah, buku ini mengulas karakteristik, habitat, serta keunikan berbagai jenis binatang buas di alam liar lewat gaya penyampaian \"bincang riang\" yang sederhana, komunikatif, dan mudah dipahami oleh pembaca cilik', 'binatang buas, hewan, fauna, pengetahuan, anak', 'assets/uploads/covers/cover_6a4f0fd2e08e04.42279504.png', NULL, '2026-06-22 08:10:57', '2026-07-09 03:04:50'),
(163, 'Bincang Riang Tentang Binatang Peliharaan', 'Bambang Trimansyah', 'Pengetahuan Hewan', NULL, 'Buku bacaan anak tentang binatang peliharaan dan cara merawatnya.', 'binatang peliharaan, hewan, perawatan, anak, pengetahuan', 'assets/uploads/covers/cover_6a4f1b1df06c44.13841900.png', NULL, '2026-06-22 08:10:57', '2026-07-09 03:53:01'),
(164, 'Bintang Keluarga', 'Mahrnis', 'Keluarga', NULL, 'Buku yang menonjolkan nilai keluarga dan hubungan antaranggota keluarga.', 'keluarga, kebersamaan, anak, nilai moral, kasih sayang', 'assets/uploads/covers/cover_6a4f1053af19e8.13726300.png', NULL, '2026-06-22 08:10:57', '2026-07-09 03:06:59'),
(165, 'Boneka-Boneka Bono', 'Thamrin Sonatha', 'Cerita Anak', NULL, 'Buku cerita anak tentang dunia boneka dan petualangan yang menyenangkan.', 'boneka, anak, permainan, cerita, imajinasi', 'assets/uploads/covers/cover_6a391b1faa6c09.22520969.jpg', NULL, '2026-06-22 08:10:57', '2026-06-22 12:40:13'),
(166, 'Bumi', 'Jendela IPTEK', 'Sains', NULL, 'buku pengetahuan tentang bumi dan isi planet kita.', 'bumi, geologi, alam semesta', 'assets/uploads/covers/cover_6a391b3fa817d8.45467437.jpg', NULL, '2026-06-22 08:10:57', '2026-07-09 05:36:04'),
(167, 'Bumiku Lestari', 'Oppie Andaresta', 'Lingkungan', NULL, 'Buku anak yang mengajarkan pentingnya menjaga bumi tetap lestari.', 'bumi, lingkungan, lestari, alam, anak', 'assets/uploads/covers/cover_6a391b598d66f9.96703933.jpg', NULL, '2026-06-22 08:10:57', '2026-06-22 12:40:13'),
(168, 'Bunda', 'Herwan F.R.', 'Cerita Anak', NULL, 'Buku setebal 40 halaman ini merupakan karya fiksi anak yang diterbitkan oleh Direktorat Pembinaan Taman Kanak-Kanak dan Sekolah Dasar. Buku \"Bunda\" terpilih sebagai salah satu karya pemenang lomba penulisan naskah bacaan siswa SD kelas rendah . Cerita di dalamnya dikemas menggunakan bahasa yang sederhana, ringan, serta dilengkapi dengan ilustrasi menarik agar cocok untuk melatih kemampuan membaca anak-anak usia dini. Tema utamanya berfokus pada nilai karakter, kasih sayang seorang ibu, serta kehangatan di dalam lingkungan keluarga.', 'Bunda, cerita anak, naskah bacaan SD, pemenang lomba penulisan, fiksi anak Indonesia', 'assets/uploads/covers/cover_6a4f2ff07b7cc0.27512045.png', NULL, '2026-06-22 08:10:57', '2026-07-09 05:21:52'),
(169, 'Cacing Adakah Gunanya?', 'Samin A.', 'Pengetahuan Alam', NULL, 'Buku yang menjelaskan manfaat cacing dalam lingkungan.', 'cacing, tanah, manfaat, hewan kecil, ekosistem', 'assets/uploads/covers/cover_6a391bb5d6a9b2.94514621.jpg', NULL, '2026-06-22 08:10:57', '2026-06-22 12:40:13'),
(170, 'Cara Cepat Menguasai 16 Tenses', 'Drs. Budiono', 'Bahasa Inggris', NULL, 'Buku panduan cepat memahami 16 tenses dalam bahasa Inggris.', 'tenses, grammar, bahasa Inggris, sekolah, pembelajaran', 'assets/uploads/covers/cover_6a391bd83c8614.81974808.jpg', NULL, '2026-06-22 08:10:57', '2026-06-22 12:40:13'),
(171, 'Cerita Indahnya Berbagi', 'Diah Kurniasari', 'Pendidikan Karakter', NULL, 'Cerita anak yang menekankan nilai berbagi dan kebaikan.', 'berbagi, kebaikan, teman, karakter, anak', 'assets/uploads/covers/cover_6a391bf12128b7.29030040.jpg', NULL, '2026-06-22 08:10:57', '2026-06-22 12:40:13'),
